def print_pattern(N):
    for i in range(1, N+1):
        if i <= N // 2:
            row = '#' * i + '.' * (N - 2*i)
        else:
            row = '.'
        print(row)

# Test the function with the provided constraints
print_pattern(11)
print_pattern(5)
print_pattern(8)
print_pattern(2)

def print_pattern(N):
    for i in range(1, N+1):
        row = ""
        for j in range(N-i+1):
            if i % 2 == 1:
                row += "#"
            else:
                row += "."
        print(row)
    for i in range(N-1, 0, -1):
        row = ""
        for j in range(N-i+1):
            if i % 2 == 1:
                row += "#"
            else:
                row += "."
        print(row)

if __name__ == "__main__":
    N = int(input())
    print_pattern(N)

def print_pattern(N):
    for i in range(1, N+1):
        row = ''
        for j in range(i):
            if i % 2 == 0:
                row += '#'
            else:
                row += '.'
        for j in range(N-i):
            if i % 2 == 0:
                row += '.'
            else:
                row += '#'
        print(row)

# Test the function with different values of N
print_pattern(11)
print_pattern(5)
print_pattern(8)
print_pattern(2)

def print_pattern(N):
    result = []
    for i in range(1, N+1):
        if i % 2 == 1:
            row = ['#' for _ in range(N)]
        else:
            row = ['.' for _ in range(N)]
        result.append(''.join(row))
    return '\n'.join(result)

# Test the function
print_pattern(11)
print_pattern(5)
print_pattern(8)
print_pattern(2)
